#include "staged_lm/pose_shape_normal_equations.h"
#include <Eigen/Dense>
#include <chrono>
#include <cmath>
#include <stdexcept>
namespace staged_lm { namespace {using Clock=std::chrono::steady_clock;double ms(Clock::time_point s){return std::chrono::duration<double,std::milli>(Clock::now()-s).count();}
std::vector<int> indices(const std::string&c){std::vector<int>x;int start=c=="cam2"?0:6;for(int i=0;i<6;++i)x.push_back(start+i);for(int i=12;i<75;++i)x.push_back(i);return x;}
PoseShapeCameraNormalEquations camera_ne(const PoseShapeCameraJacobianResult&j,const PoseCameraNormalEquations&a){PoseShapeCameraNormalEquations r;r.active=a;int rows=a.weighted_residual.size();r.weighted_jacobian_beta.resize(rows*10);auto s=Clock::now();for(int row=0;row<rows;++row)for(int b=0;b<10;++b)r.weighted_jacobian_beta[row*10+b]=j.beta_jacobian[row*10+b]*a.row_scales[row];r.beta_scaling_ms=ms(s);s=Clock::now();Eigen::Matrix<double,Eigen::Dynamic,69,Eigen::RowMajor>ja(rows,69);Eigen::Matrix<double,Eigen::Dynamic,10,Eigen::RowMajor>jb(rows,10);Eigen::VectorXd rv(rows);for(int row=0;row<rows;++row){rv[row]=a.weighted_residual[row];for(int c=0;c<69;++c)ja(row,c)=a.weighted_jacobian_active[row*69+c];for(int b=0;b<10;++b)jb(row,b)=r.weighted_jacobian_beta[row*10+b];}r.fp64_beta_cast_ms=ms(s);s=Clock::now();Eigen::Matrix<double,69,69,Eigen::RowMajor>haa=ja.transpose()*ja;r.h_aa_ms=ms(s);s=Clock::now();Eigen::Matrix<double,69,10,Eigen::RowMajor>hab=ja.transpose()*jb;r.h_ab_ms=ms(s);s=Clock::now();Eigen::Matrix<double,10,10,Eigen::RowMajor>hbb=jb.transpose()*jb;r.h_bb_ms=ms(s);s=Clock::now();Eigen::Matrix<double,10,1>gb=jb.transpose()*rv;r.gradient_ms=ms(s);r.h_active_beta.assign(hab.data(),hab.data()+hab.size());r.h_beta_beta.assign(hbb.data(),hbb.data()+hbb.size());r.g_beta.assign(gb.data(),gb.data()+gb.size());return r;}
}
PoseShapeNormalEquationsResult build_pose_shape_normal_equations(const PoseShapeCameraJacobianResult&j2,const PoseShapeCameraJacobianResult&j4,const std::vector<float>&p,const std::vector<float>&pa,const std::vector<float>&ba,const PoseShapeNormalEquationConfig&cfg){if(p.size()!=85||pa.size()!=63||ba.size()!=10)throw std::runtime_error("pose shape NE input mismatch");auto total=Clock::now();std::vector<float>frame(p.begin(),p.begin()+75);auto pose=build_pose_normal_equations(j2.pose,j4.pose,frame,pa,cfg);PoseShapeNormalEquationsResult r;r.cam2=camera_ne(j2,pose.cam2);r.cam4=camera_ne(j4,pose.cam4);auto s=Clock::now();r.a_data=pose.hessian_data_frame;r.g_frame_data=pose.gradient_data_frame;r.b_data.assign(75*10,0);r.c_data.assign(100,0);r.g_beta_data.assign(10,0);const PoseShapeCameraNormalEquations*cs[]={&r.cam2,&r.cam4};const char*names[]={"cam2","cam4"};for(int k=0;k<2;++k){auto ix=indices(names[k]);for(int i=0;i<69;++i)for(int b=0;b<10;++b)r.b_data[ix[i]*10+b]+=cs[k]->h_active_beta[i*10+b];for(int i=0;i<100;++i)r.c_data[i]+=cs[k]->h_beta_beta[i];for(int b=0;b<10;++b)r.g_beta_data[b]+=cs[k]->g_beta[b];}r.scatter_accumulate_ms=ms(s);s=Clock::now();r.a_pose_prior=pose.hessian_pose_anchor;r.g_pose_prior=pose.gradient_pose_anchor;r.pose_prior_ms=ms(s);s=Clock::now();r.c_shape_prior.assign(100,0);r.g_shape_prior.assign(10,0);for(int b=0;b<10;++b){float z=p[75+b],t=std::tanh(z),beta=2.5F*t,db=2.5F*(1-t*t),diag=db*cfg.shape_anchor_scale,res=(beta-ba[b])*cfg.shape_anchor_scale;r.c_shape_prior[b*10+b]=double(diag)*diag;r.g_shape_prior[b]=double(diag)*res;}r.shape_prior_ms=ms(s);r.a_final=r.a_data;r.b_final=r.b_data;r.c_final=r.c_data;r.g_frame_final=r.g_frame_data;r.g_beta_final=r.g_beta_data;for(size_t i=0;i<r.a_final.size();++i)r.a_final[i]+=r.a_pose_prior[i];for(int i=0;i<100;++i)r.c_final[i]+=r.c_shape_prior[i];for(int i=0;i<75;++i)r.g_frame_final[i]+=r.g_pose_prior[i];for(int i=0;i<10;++i)r.g_beta_final[i]+=r.g_shape_prior[i];r.h_dense_structured.assign(85*85,0);r.g_dense_structured.resize(85);for(int i=0;i<75;++i){r.g_dense_structured[i]=r.g_frame_final[i];for(int j=0;j<75;++j)r.h_dense_structured[i*85+j]=r.a_final[i*75+j];for(int b=0;b<10;++b){r.h_dense_structured[i*85+75+b]=r.b_final[i*10+b];r.h_dense_structured[(75+b)*85+i]=r.b_final[i*10+b];}}for(int b=0;b<10;++b){r.g_dense_structured[75+b]=r.g_beta_final[b];for(int c=0;c<10;++c)r.h_dense_structured[(75+b)*85+75+c]=r.c_final[b*10+c];}r.total_ms=ms(total);return r;}
}
